/** The calls Go makes of the host, on the UI thread. */
interface HostCalls {
    /** the app's bundle and the system's settings, asked once at start */
    fun appInfo(): AppInfoReply
    /** the appearance and the accessibility preferences */
    fun theme(): ThemeReply
    /** the appearance the app asks for: "light", "dark" or "system" */
    fun setAppearance(c: SetAppearanceCall)
    /** the screen's size in DIPs and scale */
    fun screen(): ScreenReply
    /** a line the app wrote to its standard output or error */
    fun log(c: LogCall)
    /** the screen's content: a web view, or a surface for native UI */
    fun createWindow(c: CreateWindowCall): CreateWindowReply
    fun showWindow(c: ShowWindowCall)
    fun hideWindow(c: HideWindowCall)
    fun closeWindow(c: CloseWindowCall)
    fun setBackground(c: SetBackgroundCall)
    fun focus(c: FocusCall)
    fun loadURL(c: LoadURLCall)
    fun loadHTML(c: LoadHTMLCall)
    fun reload(c: ReloadCall)
    fun stopLoading(c: StopLoadingCall)
    fun goBack(c: GoBackCall)
    fun goForward(c: GoForwardCall)
    fun eval(c: EvalCall)
    /** runs Body as an async function's; AsyncResult answers */
    fun callAsync(c: CallAsyncCall)
    fun setZoom(c: SetZoomCall)
    fun setUserAgent(c: SetUserAgentCall)
    fun setUserScripts(c: SetUserScriptsCall)
    /** a PNG of the page; Captured answers */
    fun capturePage(c: CapturePageCall)
    fun userAgent(c: UserAgentCall): UserAgentReply
    /** the status and headers of a SchemeRequest (Header: names and values in turn) */
    fun schemeRespond(c: SchemeRespondCall)
    fun schemeData(c: SchemeDataCall)
    fun schemeFinish(c: SchemeFinishCall)
    fun schemeFail(c: SchemeFailCall)
    /** an alert; MessageBoxResult answers */
    fun messageBox(c: MessageBoxCall)
    /** the system's picker of documents; FilesResult answers with copies the app may read */
    fun openFiles(c: OpenFilesCall)
    /** the share sheet of a file, as the place to save it */
    fun shareFile(c: ShareFileCall)
    fun clipboardText(): ClipboardTextReply
    fun setClipboardText(c: SetClipboardTextCall)
    /** opens a URL in the app the system has for it */
    fun openURL(c: OpenURLCall): OpenURLReply
    fun secretGet(c: SecretGetCall): SecretGetReply
    fun secretSet(c: SecretSetCall): SecretSetReply
    fun secretDelete(c: SecretDeleteCall): SecretDeleteReply
    /** a local notification; NotifyDone answers once the system has it */
    fun notify(c: NotifyCall)
    fun removeNotification(c: RemoveNotificationCall)
    fun removeAllNotifications()
    /** keeps the screen on while the app shows */
    fun keepAwake(c: KeepAwakeCall)
    /** "selection", "light", "medium", "heavy", "success", "warning" or "error" */
    fun haptic(c: HapticCall)
    /** asks for a Frame at the next refresh of the display */
    fun requestFrame(c: RequestFrameCall)
    /** where the caret of the text being edited is, and whether the keyboard shows for it */
    fun setTextInput(c: SetTextInputCall)
    /** the text around the caret changed, which the keyboard's suggestions read again */
    fun textInputChanged(c: TextInputChangedCall)
    /** the pointer's shape, for a mouse or a trackpad */
    fun setCursor(c: SetCursorCall)
    /** the tree of accessible elements changed; Focus names the one with the focus */
    fun accessibilityChanged(c: AccessibilityChangedCall)
    fun announce(c: AnnounceCall)
    /** the system's edit menu at a point, with the actions given (cut, copy, paste, selectAll and labels); MenuChosen answers */
    fun showMenu(c: ShowMenuCall)
    /** the metrics of a font (Android's Paint): ascent and descent, x-height, underline and strikethrough */
    fun textMetrics(c: TextMetricsCall): TextMetricsReply
    /** how wide each of Texts is in a font, kerned unless NoKern */
    fun measureText(c: MeasureTextCall): MeasureTextReply
    /** the advance of each UTF-16 unit of Text laid out as a whole (getTextRunAdvances) */
    fun textAdvances(c: TextAdvancesCall): TextAdvancesReply
    /** draws Text in white at Scale pixels per DIP, its pen DX pixels right of a pixel's edge: its ink's box from the pen and its pixels, a byte of coverage each, or premultiplied RGBA when Color */
    fun drawText(c: DrawTextCall): DrawTextReply
    /** adds a font file under Family, or its own family when empty */
    fun registerFont(c: RegisterFontCall): RegisterFontReply
}

/** Runs a call on h and encodes its reply, null for a call not waited for. */
fun dispatchCall(h: HostCalls, buf: ByteArray): ByteArray? {
    val r = WireReader(buf)
    val w = WireWriter()
    when (r.uvarint().toInt()) {
        1 -> { h.appInfo().encode(w); return w.toByteArray() }
        2 -> { h.theme().encode(w); return w.toByteArray() }
        3 -> h.setAppearance(SetAppearanceCall(r))
        4 -> { h.screen().encode(w); return w.toByteArray() }
        5 -> h.log(LogCall(r))
        6 -> { h.createWindow(CreateWindowCall(r)).encode(w); return w.toByteArray() }
        7 -> h.showWindow(ShowWindowCall(r))
        8 -> h.hideWindow(HideWindowCall(r))
        9 -> h.closeWindow(CloseWindowCall(r))
        10 -> h.setBackground(SetBackgroundCall(r))
        11 -> h.focus(FocusCall(r))
        12 -> h.loadURL(LoadURLCall(r))
        13 -> h.loadHTML(LoadHTMLCall(r))
        14 -> h.reload(ReloadCall(r))
        15 -> h.stopLoading(StopLoadingCall(r))
        16 -> h.goBack(GoBackCall(r))
        17 -> h.goForward(GoForwardCall(r))
        18 -> h.eval(EvalCall(r))
        19 -> h.callAsync(CallAsyncCall(r))
        20 -> h.setZoom(SetZoomCall(r))
        21 -> h.setUserAgent(SetUserAgentCall(r))
        22 -> h.setUserScripts(SetUserScriptsCall(r))
        23 -> h.capturePage(CapturePageCall(r))
        24 -> { h.userAgent(UserAgentCall(r)).encode(w); return w.toByteArray() }
        25 -> h.schemeRespond(SchemeRespondCall(r))
        26 -> h.schemeData(SchemeDataCall(r))
        27 -> h.schemeFinish(SchemeFinishCall(r))
        28 -> h.schemeFail(SchemeFailCall(r))
        29 -> h.messageBox(MessageBoxCall(r))
        30 -> h.openFiles(OpenFilesCall(r))
        31 -> h.shareFile(ShareFileCall(r))
        32 -> { h.clipboardText().encode(w); return w.toByteArray() }
        33 -> h.setClipboardText(SetClipboardTextCall(r))
        34 -> { h.openURL(OpenURLCall(r)).encode(w); return w.toByteArray() }
        35 -> { h.secretGet(SecretGetCall(r)).encode(w); return w.toByteArray() }
        36 -> { h.secretSet(SecretSetCall(r)).encode(w); return w.toByteArray() }
        37 -> { h.secretDelete(SecretDeleteCall(r)).encode(w); return w.toByteArray() }
        38 -> h.notify(NotifyCall(r))
        39 -> h.removeNotification(RemoveNotificationCall(r))
        40 -> h.removeAllNotifications()
        41 -> h.keepAwake(KeepAwakeCall(r))
        42 -> h.haptic(HapticCall(r))
        43 -> h.requestFrame(RequestFrameCall(r))
        44 -> h.setTextInput(SetTextInputCall(r))
        45 -> h.textInputChanged(TextInputChangedCall(r))
        46 -> h.setCursor(SetCursorCall(r))
        47 -> h.accessibilityChanged(AccessibilityChangedCall(r))
        48 -> h.announce(AnnounceCall(r))
        49 -> h.showMenu(ShowMenuCall(r))
        50 -> { h.textMetrics(TextMetricsCall(r)).encode(w); return w.toByteArray() }
        51 -> { h.measureText(MeasureTextCall(r)).encode(w); return w.toByteArray() }
        52 -> { h.textAdvances(TextAdvancesCall(r)).encode(w); return w.toByteArray() }
        53 -> { h.drawText(DrawTextCall(r)).encode(w); return w.toByteArray() }
        54 -> { h.registerFont(RegisterFontCall(r)).encode(w); return w.toByteArray() }
    }
    return null
}

/** Encodes the events the host sends Go. */
object Event {
    /** the app finished launching */
    @JvmStatic fun ready(): ByteArray {
        val w = WireWriter()
        w.uvarint(1)
        return w.toByteArray()
    }
    /** the app is in front, or no longer */
    @JvmStatic fun active(active: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(2)
        w.bool(active)
        return w.toByteArray()
    }
    /** the app went to the background (true) or came back */
    @JvmStatic fun background(background: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(3)
        w.bool(background)
        return w.toByteArray()
    }
    @JvmStatic fun themeChanged(): ByteArray {
        val w = WireWriter()
        w.uvarint(4)
        return w.toByteArray()
    }
    @JvmStatic fun localeChanged(): ByteArray {
        val w = WireWriter()
        w.uvarint(5)
        return w.toByteArray()
    }
    @JvmStatic fun openURLs(urls: List<String>): ByteArray {
        val w = WireWriter()
        w.uvarint(6)
        w.strings(urls)
        return w.toByteArray()
    }
    @JvmStatic fun memoryWarning(): ByteArray {
        val w = WireWriter()
        w.uvarint(7)
        return w.toByteArray()
    }
    @JvmStatic fun terminating(): ByteArray {
        val w = WireWriter()
        w.uvarint(8)
        return w.toByteArray()
    }
    /** the window's size in DIPs, the scale, and the insets of what covers it: the system's bars, the cutout, the keyboard */
    @JvmStatic fun resized(id: Long, width: Double, height: Double, scale: Double, safeTop: Double, safeLeft: Double, safeBottom: Double, safeRight: Double, keyboard: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(9)
        w.int(id)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(safeTop)
        w.float(safeLeft)
        w.float(safeBottom)
        w.float(safeRight)
        w.float(keyboard)
        return w.toByteArray()
    }
    /** Android's back: whether the app took it */
    @JvmStatic fun backPressed(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(10)
        w.int(id)
        return w.toByteArray()
    }
    /** a message the page's bridge posted */
    @JvmStatic fun message(id: Long, text: String): ByteArray {
        val w = WireWriter()
        w.uvarint(11)
        w.int(id)
        w.string(text)
        return w.toByteArray()
    }
    @JvmStatic fun willNavigate(id: Long, url: String, mainFrame: Boolean, userInitiated: Boolean, unasked: Boolean, reload: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(12)
        w.int(id)
        w.string(url)
        w.bool(mainFrame)
        w.bool(userInitiated)
        w.bool(unasked)
        w.bool(reload)
        return w.toByteArray()
    }
    /** window.open or a link to _blank: whether the app opened it */
    @JvmStatic fun newWindow(id: Long, url: String, userInitiated: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(13)
        w.int(id)
        w.string(url)
        w.bool(userInitiated)
        return w.toByteArray()
    }
    /** what the page is at, after any change of it */
    @JvmStatic fun pageState(id: Long, url: String, title: String, loading: Boolean, canGoBack: Boolean, canGoForward: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(14)
        w.int(id)
        w.string(url)
        w.string(title)
        w.bool(loading)
        w.bool(canGoBack)
        w.bool(canGoForward)
        return w.toByteArray()
    }
    @JvmStatic fun navigationStarted(id: Long, url: String): ByteArray {
        val w = WireWriter()
        w.uvarint(15)
        w.int(id)
        w.string(url)
        return w.toByteArray()
    }
    @JvmStatic fun navigationCommitted(id: Long, url: String): ByteArray {
        val w = WireWriter()
        w.uvarint(16)
        w.int(id)
        w.string(url)
        return w.toByteArray()
    }
    @JvmStatic fun loadFinished(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(17)
        w.int(id)
        return w.toByteArray()
    }
    @JvmStatic fun loadFailed(id: Long, url: String, code: Long, description: String): ByteArray {
        val w = WireWriter()
        w.uvarint(18)
        w.int(id)
        w.string(url)
        w.int(code)
        w.string(description)
        return w.toByteArray()
    }
    @JvmStatic fun closedByPage(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(19)
        w.int(id)
        return w.toByteArray()
    }
    @JvmStatic fun processGone(id: Long, reason: String): ByteArray {
        val w = WireWriter()
        w.uvarint(20)
        w.int(id)
        w.string(reason)
        return w.toByteArray()
    }
    @JvmStatic fun permissionRequested(id: Long, kinds: List<String>, origin: String): ByteArray {
        val w = WireWriter()
        w.uvarint(21)
        w.int(id)
        w.strings(kinds)
        w.string(origin)
        return w.toByteArray()
    }
    /** a request of one of the app's schemes (Header: names and values in turn) */
    @JvmStatic fun schemeRequest(id: Long, req: Long, method: String, url: String, header: List<String>, body: ByteArray, hasBody: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(22)
        w.int(id)
        w.int(req)
        w.string(method)
        w.string(url)
        w.strings(header)
        w.bytes(body)
        w.bool(hasBody)
        return w.toByteArray()
    }
    @JvmStatic fun schemeCancel(req: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(23)
        w.int(req)
        return w.toByteArray()
    }
    @JvmStatic fun asyncResult(req: Long, result: String, error: String): ByteArray {
        val w = WireWriter()
        w.uvarint(24)
        w.int(req)
        w.string(result)
        w.string(error)
        return w.toByteArray()
    }
    @JvmStatic fun captured(req: Long, png: ByteArray, error: String): ByteArray {
        val w = WireWriter()
        w.uvarint(25)
        w.int(req)
        w.bytes(png)
        w.string(error)
        return w.toByteArray()
    }
    @JvmStatic fun messageBoxResult(req: Long, response: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(26)
        w.int(req)
        w.int(response)
        return w.toByteArray()
    }
    @JvmStatic fun filesResult(req: Long, paths: List<String>, error: String): ByteArray {
        val w = WireWriter()
        w.uvarint(27)
        w.int(req)
        w.strings(paths)
        w.string(error)
        return w.toByteArray()
    }
    @JvmStatic fun notifyDone(req: Long, error: String): ByteArray {
        val w = WireWriter()
        w.uvarint(28)
        w.int(req)
        w.string(error)
        return w.toByteArray()
    }
    @JvmStatic fun notificationClicked(notificationID: String): ByteArray {
        val w = WireWriter()
        w.uvarint(29)
        w.string(notificationID)
        return w.toByteArray()
    }
    /** the display refreshes: draw a frame if one was asked for */
    @JvmStatic fun frame(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(30)
        w.int(id)
        return w.toByteArray()
    }
    /** the native surface to draw on (a CAMetalLayer, an ANativeWindow), 0 when gone */
    @JvmStatic fun surfaceChanged(id: Long, handle: Long, width: Double, height: Double, scale: Double, refresh: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(31)
        w.int(id)
        w.int(handle)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(refresh)
        return w.toByteArray()
    }
    /** the native surface goes: the host waits for Go to let go of it */
    @JvmStatic fun surfaceDestroyed(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(32)
        w.int(id)
        return w.toByteArray()
    }
    /** a finger, a pen or a mouse: Phase is "down", "move", "up" or "cancel", Kind "touch", "pen" or "mouse" */
    @JvmStatic fun touch(id: Long, pointer: Long, phase: String, kind: String, x: Double, y: Double, pressure: Double, buttons: Long, time: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(33)
        w.int(id)
        w.int(pointer)
        w.string(phase)
        w.string(kind)
        w.float(x)
        w.float(y)
        w.float(pressure)
        w.int(buttons)
        w.float(time)
        return w.toByteArray()
    }
    /** a mouse's or a trackpad's scrolling, in DIPs */
    @JvmStatic fun scroll(id: Long, x: Double, y: Double, dx: Double, dy: Double, precise: Boolean, phase: String): ByteArray {
        val w = WireWriter()
        w.uvarint(34)
        w.int(id)
        w.float(x)
        w.float(y)
        w.float(dx)
        w.float(dy)
        w.bool(precise)
        w.string(phase)
        return w.toByteArray()
    }
    /** a hardware keyboard's key: Down, its name (as ui names keys) and the text it types */
    @JvmStatic fun key(id: Long, down: Boolean, key: String, text: String, mods: Long, repeated: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(35)
        w.int(id)
        w.bool(down)
        w.string(key)
        w.string(text)
        w.int(mods)
        w.bool(repeated)
        return w.toByteArray()
    }
    /** the keyboard typed Text, in place of the marked text if any */
    @JvmStatic fun textInsert(id: Long, text: String): ByteArray {
        val w = WireWriter()
        w.uvarint(36)
        w.int(id)
        w.string(text)
        return w.toByteArray()
    }
    /** the input method's text being composed, its selection in runes */
    @JvmStatic fun textMarked(id: Long, text: String, selStart: Long, selEnd: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(37)
        w.int(id)
        w.string(text)
        w.int(selStart)
        w.int(selEnd)
        return w.toByteArray()
    }
    /** the keyboard deleted Before runes before the caret and After after it */
    @JvmStatic fun textDelete(id: Long, before: Long, after: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(38)
        w.int(id)
        w.int(before)
        w.int(after)
        return w.toByteArray()
    }
    /** an editing action of the keyboard or the edit menu: "newline", "tab", "cut", "copy", "paste", "selectAll", "left", … */
    @JvmStatic fun textCommand(id: Long, command: String): ByteArray {
        val w = WireWriter()
        w.uvarint(39)
        w.int(id)
        w.string(command)
        return w.toByteArray()
    }
    /** the text around the caret and the selection, in runes, for the keyboard's suggestions */
    @JvmStatic fun textState(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(40)
        w.int(id)
        return w.toByteArray()
    }
    /** the keyboard moved the caret or the selection, by runes from the caret */
    @JvmStatic fun textSelect(id: Long, start: Long, end: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(41)
        w.int(id)
        w.int(start)
        w.int(end)
        return w.toByteArray()
    }
    /** the keyboard went away */
    @JvmStatic fun textInputEnded(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(42)
        w.int(id)
        return w.toByteArray()
    }
    @JvmStatic fun menuChosen(id: Long, req: Long, action: String): ByteArray {
        val w = WireWriter()
        w.uvarint(43)
        w.int(id)
        w.int(req)
        w.string(action)
        return w.toByteArray()
    }
    /** the accessible elements, encoded as Nodes: for each, its ID, parent, role, label, value, hint, frame and actions */
    @JvmStatic fun accessibilityTree(id: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(44)
        w.int(id)
        return w.toByteArray()
    }
    /** an assistive technology's action on an element: "press", "increment", "decrement", "focus", "scrollForward", … */
    @JvmStatic fun accessibilityAction(id: Long, node: Long, action: String): ByteArray {
        val w = WireWriter()
        w.uvarint(45)
        w.int(id)
        w.int(node)
        w.string(action)
        return w.toByteArray()
    }
}

class BackPressedReply(
    @JvmField var handled: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        handled = r.bool()
    }
}

class WillNavigateReply(
    @JvmField var allow: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        allow = r.bool()
    }
}

class NewWindowReply(
    @JvmField var handled: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        handled = r.bool()
    }
}

class PermissionRequestedReply(
    @JvmField var allow: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        allow = r.bool()
    }
}

class SurfaceDestroyedReply() {
    constructor(r: WireReader) : this() {
    }
}

class KeyReply(
    @JvmField var handled: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        handled = r.bool()
    }
}

class TextStateReply(
    @JvmField var before: String = "",
    @JvmField var selected: String = "",
    @JvmField var after: String = "",
    @JvmField var marked: Long = 0L,
    @JvmField var caretX: Double = 0.0,
    @JvmField var caretY: Double = 0.0,
    @JvmField var caretHeight: Double = 0.0,
) {
    constructor(r: WireReader) : this() {
        before = r.string()
        selected = r.string()
        after = r.string()
        marked = r.int()
        caretX = r.float()
        caretY = r.float()
        caretHeight = r.float()
    }
}

class AccessibilityTreeReply(
    @JvmField var nodes: ByteArray = ByteArray(0),
) {
    constructor(r: WireReader) : this() {
        nodes = r.bytes()
    }
}

class AccessibilityActionReply(
    @JvmField var handled: Boolean = false,
) {
    constructor(r: WireReader) : this() {
        handled = r.bool()
    }
}
